# tiktoken needs to be installed and downloads its vocabulary, which this sandbox
# cannot do. ToyTokenizer works the same way on a small scale: it splits text into
# subword tokens by greedy longest match over a fixed vocabulary, and every token has
# an integer id. Unknown words fall back to single characters.
class ToyTokenizer:
    PIECES = ["Python", " is", " the", " best", " programming", " program", "ming", " language",
              " for", " AI", " development", " develop", "ment", "."]

    def __init__(self):
        self.vocab = self.PIECES + [chr(i) for i in range(32, 127)]
        self.ids = {piece: i for i, piece in enumerate(self.vocab)}

    def encode(self, text):
        ids, i = [], 0
        while i < len(text):
            match = max((p for p in self.vocab if text.startswith(p, i)), key=len)
            ids.append(self.ids[match])
            i += len(match)
        return ids

    def decode(self, ids):
        return "".join(self.vocab[i] for i in ids)


def analyze_tokens(text, tokenizer, price_per_million=0.15):
    """Return {"token_count": int, "tokens": [str, ...], "estimated_cost": float}."""
    ids = tokenizer.encode(text)
    tokens = [tokenizer.decode([i]) for i in ids]
    return {
        "token_count": len(ids),
        "tokens": tokens,
        "estimated_cost": len(ids) * price_per_million / 1_000_000,
    }


result = analyze_tokens("Python is the best programming language for AI development.", ToyTokenizer())
if result is None:
    print("analyze_tokens() returned None")
else:
    print(f"Token count: {result['token_count']}")
    print(f"Tokens: {result['tokens']}")
    print(f"Estimated cost: ${result['estimated_cost']:.8f}")
